function UIFightTeamSweepTimesExplainTips:Show()
    local playerDojo = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent).playerDojo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)
    local isHavePrivilegeCard = playerDojo:IsHavePrivilegeCardById(tonumber(vo.giftId))

    local normalFreeTimes = checkInt(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 23).num)
    local vipFreeTimes = checkInt(GameUtils.GetPrivilegeCardAddNumByName(tonumber(vo.giftId), "autoNum")) or 10

    KTool.SetActive(self.RT_VIPLock, not isHavePrivilegeCard)
    self.STxt_VIPSweep.Status = isHavePrivilegeCard and 2 or 1
    self.Txt_VIPSweep.text = localize('每日特权扫荡：<size=36>_num_</size>', {_num_ = vipFreeTimes})
    self.Txt_NormalSweep.text = localize('每日普通扫荡：<size=36>_num_</size>', {_num_ = normalFreeTimes})
end

return UIFightTeamSweepTimesExplainTips